/// Schema version stamped into every [`RouteReport`] this crate writes.
///
/// Part of the run-record contract: a consumer that cannot parse the
/// schema it expects should be able to see which one it got rather than
/// silently misread a field.
pub const ROUTE_REPORT_SCHEMA: &str = "synth.routing.v1";

/// Run `engine` over the board at [`RouteRequest::board_path`] and report
/// what came back.
///
/// This is the single entry point every surface (CLI, MCP, renderer, SaaS)
/// routes a board through, so the router identity and terminal state they
/// report cannot diverge between layers.
///
/// The returned [`RouteReport`] is written to
/// [`RouteRequest::report_path`] before this function returns, so a run
/// that fails is as auditable as one that succeeds.
pub fn route(request: &RouteRequest) -> RouteReport {
    let mut report = route_once(request);
    if request.engine != RouterEngine::KiCadRoutingTools {
        return report;
    }
    // Whether the engine puts a via in a pad, or leaves a net open, depends on
    // the order it routes the nets in, and the same board can route cleanly in
    // one order and not in another. A board the independent validation rejected
    // is therefore tried again in the engine's other orders before it is given
    // up on; the first one that validates is kept.
    for ordering in ORDERING_RETRIES.iter().take(ordering_retries()) {
        if report.state != result::RouteState::ValidationFailed {
            break;
        }
        eprintln!(
            "note: the routed board was rejected ({} blocking); routing again with the {ordering} net order",
            report
                .validation
                .as_ref()
                .map_or(0, result::ValidationSummary::blocking_count)
        );
        let mut again = request.clone();
        again.kicad_routing_tools.ordering = Some((*ordering).to_string());
        report = route_once(&again);
    }
    report
}

/// The engine's net orders other than its default, in the order they are tried.
const ORDERING_RETRIES: [&str; 3] = ["inside_out", "original", "bus"];

/// How many of [`ORDERING_RETRIES`] a rejected board is tried with:
/// `SYNTH_ROUTER_ORDERING_RETRIES`, three when absent, none when zero.
fn ordering_retries() -> usize {
    std::env::var("SYNTH_ROUTER_ORDERING_RETRIES")
        .ok()
        .and_then(|v| v.trim().parse::<usize>().ok())
        .unwrap_or(ORDERING_RETRIES.len())
}

fn route_once(request: &RouteRequest) -> RouteReport {
    // The duplicate-run guard is taken first. Reporting "router
    // unavailable" while a run is already writing this candidate would name
    // the wrong problem, and the operator would go looking for a missing
    // install that is not the issue.
    let _guard = match process::RunGuard::acquire(request.candidate_path().display().to_string()) {
        Ok(guard) => guard,
        Err(detail) => {
            let report = RouteReport::failed(
                request,
                &None,
                failure::RouterFailure::for_stage(
                    request.engine,
                    RouterStage::Route,
                    RouterFailureReason::SpawnFailed,
                    detail,
                ),
            );
            write_report(&report, request);
            return report;
        }
    };

    // The baseline must exist before any engine reads it. Do it here rather
    // than trusting the caller, so a portfolio that runs each engine in its
    // own directory gets a baseline in each without a second setup step.
    if let Err(failure) = request.preserve_baseline() {
        let mut report = RouteReport::failed(request, &None, failure);
        report.escape = escape::analyse_baseline(request);
        write_report(&report, request);
        return report;
    }

    let capability = capability::discover(request);
    if let Some(failure) = capability.failure() {
        let mut report = RouteReport::unavailable(request, &Some(capability.clone()), failure);
        report.escape = escape::analyse_baseline(request);
        write_report(&report, request);
        return report;
    }

    let run = match request.engine {
        RouterEngine::Freerouting => freerouting::route(request),
        RouterEngine::KiCadRoutingTools => kicad_routing_tools::route(request),
    };

    let mut report = match run {
        Ok(candidate) => finalize(request, Some(&capability), candidate),
        Err(failure) => RouteReport::failed(request, &Some(capability), failure),
    };
    // A property of the design and the process, not of the attempt, so it is
    // reported whatever the run did — including when the engine was missing.
    report.escape = escape::analyse_baseline(request);
    write_report(&report, request);
    report
}

/// Run every engine over the board and keep the best attempt.
///
/// Both engines are installed and they disagree on the same board — one may
/// complete a net the other cannot, or use far fewer vias. Running them and
/// choosing by the independent verdict (never by the engines' own opinion) is
/// strictly better than picking one up front, and it costs only the extra
/// route.
///
/// Each engine gets its own output directory, so no attempt clobbers another
/// and every attempt's artifacts survive for inspection. The winner is chosen
/// by [`RouteReport::portfolio_rank`]: state first, then blocking findings,
/// vias, copper length, and finally engine name so the result is deterministic.
///
/// An engine that is not installed contributes a `RouterUnavailable` report and
/// never wins over one that produced a board, so a portfolio degrades to the
/// engines that are present instead of failing.
#[must_use]
pub fn route_best_of(base: &RouteRequest, engines: &[RouterEngine]) -> Portfolio {
    let mut attempts = Vec::with_capacity(engines.len());
    for engine in engines {
        let mut request = base.clone();
        request.engine = *engine;
        request.out_dir = base.out_dir.join(engine.artifact_tag());
        attempts.push(route(&request));
    }

    let mut winner = 0usize;
    for index in 1..attempts.len() {
        if attempts[index].portfolio_rank() > attempts[winner].portfolio_rank() {
            winner = index;
        }
    }
    Portfolio {
        winner: engines.get(winner).copied().unwrap_or(base.engine),
        attempts,
    }
}

/// The result of a portfolio run: every attempt, and which engine won.
#[derive(Debug, Clone)]
pub struct Portfolio {
    /// The engine whose attempt was chosen.
    pub winner: RouterEngine,
    /// Every attempt, in the order the engines were tried.
    pub attempts: Vec<RouteReport>,
}

impl Portfolio {
    /// The winning attempt.
    ///
    /// # Panics
    /// Never in practice: [`route_best_of`] pushes exactly one attempt per
    /// engine and is never called with an empty engine list. The fallback
    /// exists so a future caller cannot index out of bounds.
    #[must_use]
    pub fn report(&self) -> &RouteReport {
        // `route_best_of` always pushes one attempt per engine, and `engines`
        // is never empty in practice; fall back to the first defensively.
        self.attempts
            .iter()
            .find(|report| report.engine == self.winner)
            .or_else(|| self.attempts.first())
            .expect("a portfolio always has at least one attempt")
    }
}

/// Reduce a design name to a filesystem-safe stem.
///
/// Shared with the exporter so run-record filenames line up with the
/// artifacts they describe, however the design was spelled.
#[must_use]
pub fn sanitize_stem(name: &str) -> String {
    let mut out = String::with_capacity(name.len());
    for c in name.chars() {
        if c.is_ascii_alphanumeric() || c == '_' || c == '-' {
            out.push(c);
        } else {
            out.push('_');
        }
    }
    if out.is_empty() {
        "untitled".to_string()
    } else {
        out
    }
}

/// Best-effort write of the run record.
///
/// A report that cannot be written must not turn a routing outcome into a
/// different outcome: the caller still gets the in-memory verdict, and the
/// problem surfaces as a warning. Losing the verdict would be the worse
/// failure.
fn write_report(report: &RouteReport, request: &RouteRequest) {
    if let Err(error) = report.write_to(&request.report_path()) {
        eprintln!(
            "warning: routing run record could not be written to {}: {error}",
            request.report_path().display()
        );
    }
}

/// The verdict with the findings of the mandatory island repair added. A
/// repair that did not run is a required check that could not be performed,
/// which is review-required; an island it left untied is a blocking finding.
/// Either way the candidate is not fabrication-ready, whatever the other checks
/// said.
fn with_repair_findings(
    mut verdict: validate::FabricationVerdict,
    blocking: Vec<String>,
    unavailable: Vec<String>,
) -> validate::FabricationVerdict {
    if !blocking.is_empty() || !unavailable.is_empty() {
        verdict.fabrication_ready = false;
        verdict.blocking_reasons.extend(blocking);
        verdict.unavailable_checks.extend(unavailable);
    }
    verdict
}

/// Promote a router-produced candidate into a report, installing it only if
/// it survives independent validation.
///
/// The ordering is the point. Validation reads the candidate from disk and
/// never consults the router's summary for connectivity, so a router that
/// over-reports its own success cannot promote itself. A candidate that
/// fails validation is still retained on disk as review material — it is
/// just never installed over the baseline.
fn finalize(
    request: &RouteRequest,
    capability: Option<&RouterCapability>,
    candidate: freerouting::Candidate,
) -> RouteReport {
    // A pour that tracks cut into regions leaves some of them tied to nothing
    // else. Tie each back before the candidate is judged, so the verdict is on
    // the board that would be delivered. The repair is mandatory: when it did
    // not run, or an island is left that it cannot tie, the candidate is not
    // promoted, because the island is a zone against itself and KiCad refuses it.
    let mut repair_blocking: Vec<String> = Vec::new();
    let mut repair_unavailable: Vec<String> = Vec::new();
    // A via the engine left in a pad of its own net is moved off it, with the tracks
    // that meet it, before the candidate is judged; the judging is unchanged.
    match island_vias::move_vias_off_pads(&candidate.candidate_path) {
        Ok(0) => {}
        Ok(moved) => eprintln!("note: moved {moved} via(s) off the pads they sat in"),
        Err(detail) => eprintln!("warning: vias in pads were not repaired: {detail}"),
    }
    match island_vias::tie_islands(&candidate.candidate_path, &request.ground_nets) {
        Ok(outcome) => repair_blocking = outcome.unresolved,
        Err(detail) => {
            eprintln!(
                "warning: pour islands were not checked in {}: {detail}",
                candidate.candidate_path.display()
            );
            repair_unavailable.push(format!("pour island repair did not run: {detail}"));
        }
    }
    let verdict = with_repair_findings(
        validate_candidate(request, &candidate),
        repair_blocking,
        repair_unavailable,
    );

    let state = RouteReport::state_for_verdict(&verdict);

    // Only a validated candidate is allowed to become the delivered
    // board. `install` is a rename, so the baseline survives either way:
    // a rejected candidate is left on disk as review material, and the
    // delivered path still holds the un-routed export.
    if state.is_fabrication_ready() {
        // The labels were placed before the router put its vias down; move any
        // that now sit on a via or a pad. Silkscreen only: the copper the
        // candidate was validated on is untouched.
        match label_vias::keep_labels_off_copper(&candidate.candidate_path) {
            Ok(label_vias::LabelMoves { moved: 0, hidden: 0 }) => {}
            Ok(label_vias::LabelMoves { moved, hidden }) => eprintln!(
                "note: moved {moved} reference label(s) off vias and pads; {hidden} hidden because no clear spot was within reach"
            ),
            Err(detail) => eprintln!("warning: reference labels were not checked: {detail}"),
        }
        // Deliver the zones filled so KiCad opens the board with the
        // connectivity it was validated with. A refill that fails leaves
        // the routed, unfilled board in place.
        if let Err(detail) = zone_fill::refill_zones(&candidate.candidate_path) {
            eprintln!(
                "warning: zones were not filled in {}: {detail}; KiCad will show \
                 plane-connected pads as unrouted until zones are filled (press B)",
                request.board_path.display()
            );
        }
        if let Err(detail) = candidate.install(&request.board_path) {
            return RouteReport::failed(
                request,
                &capability.cloned(),
                RouterFailure::for_stage(
                    request.engine,
                    RouterStage::Install,
                    RouterFailureReason::Io,
                    format!("validated candidate could not be installed: {detail}"),
                ),
            );
        }
    }

    let mut statistics = candidate.statistics.clone();
    // The router's own open-net claim is kept for provenance, but the
    // connectivity pass is what fills the fields the report reports on.
    statistics.connected_nets = verdict.connectivity.connected_nets;
    statistics.open_nets = verdict.connectivity.open_nets;
    if statistics.open_net_names.is_empty() {
        statistics.open_net_names = verdict
            .connectivity
            .open
            .iter()
            .map(|o| o.net.clone())
            .collect();
    }

    let recommended_routing_order = recommended_order(&verdict.connectivity.open);

    RouteReport {
        schema_version: ROUTE_REPORT_SCHEMA.to_string(),
        state,
        engine: request.engine,
        capability: capability.cloned(),
        provenance: candidate.provenance,
        statistics,
        artifacts: candidate.artifacts,
        validation: Some(crate::result::ValidationSummary {
            fabrication_ready: verdict.fabrication_ready,
            topology: verdict.topology,
            connectivity: verdict.connectivity,
            kicad_drc: verdict.kicad_drc,
            blocking_reasons: verdict.blocking_reasons,
            unavailable_checks: verdict.unavailable_checks,
        }),
        failure: None,
        escape: Vec::new(),
        recommended_routing_order,
    }
}

/// Net names to try first on a retry, hardest first.
///
/// "Hardest" is the net with the most pads that still failed, tie-broken by
/// the smallest stranded island: a 21-pad net that did not complete is the
/// one worth reserving routes for, not a two-pad net that merely lost its
/// second endpoint. Deterministic, so the advice does not move between runs.
fn recommended_order(open: &[crate::validate::OpenConnection]) -> Vec<String> {
    let mut nets: Vec<&crate::validate::OpenConnection> = open.iter().collect();
    nets.sort_by(|a, b| {
        b.pad_count
            .cmp(&a.pad_count)
            .then(a.island_size.cmp(&b.island_size))
            .then(a.net.cmp(&b.net))
    });
    let mut names: Vec<String> = Vec::new();
    for connection in nets {
        if !names.iter().any(|name| name == &connection.net) {
            names.push(connection.net.clone());
        }
    }
    names
}

/// Write any serializable artifact to `path` as pretty JSON.
///
/// Used by callers that retain a specific artifact — a connectivity report,
/// say — alongside the run record, so every file in a run directory is
/// machine-readable rather than a mixture of JSON and prose.
pub fn write_artifact<T: serde::Serialize>(path: &Path, value: &T) -> std::io::Result<()> {
    write_json(path, value)
}

/// Write `report` to `path` as pretty JSON, returning whether it landed.
///
/// A report that cannot be written is not silently dropped: the caller
/// still returns the in-memory report, but the artifact set records
/// [`ArtifactPresence::Missing`](result::ArtifactPresence::Missing) so a
/// consumer comparing the two can tell the difference.
pub(crate) fn write_json<T: serde::Serialize>(path: &Path, value: &T) -> std::io::Result<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    let text = serde_json::to_string_pretty(value)
        .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))?;
    std::fs::write(path, text)
}

/// Resolve a helper script shipped in the repository's `tools/` directory.
///
/// Returns `None` rather than erroring when the tool is absent so that a
/// checkout without `tools/` reports "unavailable", which is actionable,
/// instead of an opaque I/O failure.
pub(crate) fn repo_tool(name: &str) -> Option<PathBuf> {
    let root = repo_root()?;
    let candidate = root.join("tools").join(name);
    candidate.is_file().then_some(candidate)
}

/// Best-effort repository root.
///
/// Prefers `CARGO_MANIFEST_DIR` (correct for a binary run out of a build
/// tree), then walks up from the current directory (correct for a binary run
/// inside a checkout), then from the binary's own location (correct for a
/// binary built in a checkout and run from anywhere, such as an MCP server
/// started in an empty workspace).
pub(crate) fn repo_root() -> Option<PathBuf> {
    if let Ok(manifest) = std::env::var("CARGO_MANIFEST_DIR") {
        let path = PathBuf::from(manifest);
        if path.join("tools").is_dir() {
            return Some(path);
        }
        if let Some(up) = path.parent().and_then(Path::parent) {
            if up.join("tools").is_dir() {
                return Some(up.to_path_buf());
            }
        }
    }
    std::env::current_dir()
        .ok()
        .and_then(|dir| checkout_above(&dir))
        .or_else(|| {
            let exe = std::env::current_exe().ok()?;
            checkout_above(exe.parent()?)
        })
}

/// The nearest ancestor of `start`, itself included, holding both `tools/` and
/// `registry/`.
fn checkout_above(start: &Path) -> Option<PathBuf> {
    start
        .ancestors()
        .find(|dir| dir.join("tools").is_dir() && dir.join("registry").is_dir())
        .map(Path::to_path_buf)
}

#[cfg(test)]
mod checkout_tests {
    use super::*;

    #[test]
    fn a_checkout_is_found_from_any_directory_inside_it() {
        let root = std::env::temp_dir().join(format!("synth_checkout_{}", std::process::id()));
        let nested = root.join("target").join("release");
        std::fs::create_dir_all(&nested).expect("scratch");
        std::fs::create_dir_all(root.join("tools")).expect("tools");
        std::fs::create_dir_all(root.join("registry")).expect("registry");

        assert_eq!(checkout_above(&nested).as_deref(), Some(root.as_path()));
        assert_eq!(checkout_above(&root).as_deref(), Some(root.as_path()));

        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn a_directory_with_only_tools_is_not_a_checkout() {
        let root = std::env::temp_dir().join(format!("synth_not_checkout_{}", std::process::id()));
        std::fs::create_dir_all(root.join("tools")).expect("scratch");

        assert_ne!(checkout_above(&root).as_deref(), Some(root.as_path()));

        let _ = std::fs::remove_dir_all(&root);
    }
}

#[cfg(test)]
mod repair_tests {
    use super::*;
    use crate::validate::FabricationVerdict;

    #[test]
    fn a_repair_that_did_not_run_keeps_a_clean_candidate_from_being_promoted() {
        let verdict = with_repair_findings(
            FabricationVerdict::ready(),
            Vec::new(),
            vec!["pour island repair did not run: kicad-cli missing".to_string()],
        );
        assert!(!verdict.fabrication_ready);
        assert_eq!(verdict.unavailable_checks.len(), 1);
        assert_eq!(
            RouteReport::state_for_verdict(&verdict),
            RouteState::ReviewRequired,
            "a required check that could not run is review-required"
        );
    }

    #[test]
    fn an_island_the_repair_could_not_tie_blocks_the_candidate() {
        let verdict = with_repair_findings(
            FabricationVerdict::ready(),
            vec!["an island of net GND holds copper but is tied to nothing".to_string()],
            Vec::new(),
        );
        assert!(!verdict.fabrication_ready);
        assert_eq!(verdict.blocking_reasons.len(), 1);
        assert_eq!(
            RouteReport::state_for_verdict(&verdict),
            RouteState::ValidationFailed
        );
    }

    #[test]
    fn a_clean_repair_leaves_the_verdict_as_it_was() {
        let verdict = with_repair_findings(FabricationVerdict::ready(), Vec::new(), Vec::new());
        assert!(verdict.fabrication_ready);
        assert_eq!(RouteReport::state_for_verdict(&verdict), RouteState::Routed);
    }
}

#[cfg(test)]
mod order_tests {
    use super::*;
    use crate::validate::OpenConnection;

    #[test]
    fn the_hardest_open_net_is_recommended_first() {
        let open = vec![
            OpenConnection {
                net: "net_8".to_string(),
                pad: "U2.30".to_string(),
                island_size: 1,
                pad_count: 2,
            },
            OpenConnection {
                net: "net_1".to_string(),
                pad: "D1.2".to_string(),
                island_size: 1,
                pad_count: 33,
            },
            OpenConnection {
                net: "net_4".to_string(),
                pad: "U2.9".to_string(),
                island_size: 3,
                pad_count: 19,
            },
        ];
        assert_eq!(
            recommended_order(&open),
            vec![
                "net_1".to_string(),
                "net_4".to_string(),
                "net_8".to_string()
            ]
        );
    }

    #[test]
    fn a_clean_run_recommends_nothing() {
        assert!(recommended_order(&[]).is_empty());
    }
}
